function BookPage({
  books,
  loading,
  updateBook,
  onStatus,
  busy,
  notify,
  onDelete,
}) {
  const { id } = useParams();
  const navigate = useNavigate();
  const book = books.find((book) => book.id === id);
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState("");
  const [shareOpen, setShareOpen] = useState(false);
  useEffect(() => {
    setNotes(book?.notes || "");
  }, [book?.id, book?.notes]);
  useEffect(() => {
    document.title = book
      ? `${book.title} — Marginalia`
      : "Marginalia — Your reading space";
    return () => {
      document.title = "Marginalia — Your reading space";
    };
  }, [book?.title]);
  async function saveNotes() {
    setSaving(true);
    setError("");
    try {
      const updated = await api(`/${id}`, { method: "PATCH", body: { notes } });
      updateBook(updated);
      notify("Your thoughts, saved.");
    } catch (error) {
      setError(error.message);
    } finally {
      setSaving(false);
    }
  }
    </div>
  );
}

function App() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [busy, setBusy] = useState(null);
  const [toast, setToast] = useState(null);
  const toastTimer = useRef(null);
  const location = useLocation();
  async function refresh() {
    setLoading(true);
    setError("");
    try {
      setBooks(await api());
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  }
  useEffect(() => {
    refresh();
    return () => clearTimeout(toastTimer.current);
  }, []);
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [location.pathname]);
  function notify(message, type = "success") {
    clearTimeout(toastTimer.current);
    setToast({ message, type });
    toastTimer.current = setTimeout(() => setToast(null), 4500);
  }
  function updateBook(updated) {
    setBooks((books) =>
      books.map((book) => (book.id === updated.id ? updated : book)),
    );
  }
  async function changeStatus(book) {
    if (busy) return;
    setBusy(book.id);
    const status = book.status === "reading" ? "finished" : "reading";
    try {
      updateBook(
        await api(`/${book.id}`, { method: "PATCH", body: { status } }),
      );
      notify(
        status === "finished"
          ? "Another story, beautifully finished."
          : "Back on your currently reading shelf.",
      );
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setBusy(null);
    }
  }
  const isDetail = location.pathname.startsWith("/books/");
  return (
    <>
      <Sidebar
        books={books}
        open={sidebarOpen}
        close={() => setSidebarOpen(false)}
      />
      <div className="mobile-bar">
        <Link to="/" className="mobile-brand">
          <BookOpenText size={22} />
          marginalia
        </Link>
        <button
          className="icon-button"
          aria-label="Open navigation"
          onClick={() => setSidebarOpen(true)}
        >
          <Menu size={23} />
        </button>

