import {mkdtemp,rm,readFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
const dir=await mkdtemp(join(tmpdir(),'marginalia-restart-'));
const file=join(dir,'books.json');
const start=()=>new Promise((resolve,reject)=>{
 const p=spawn(process.execPath,['server/index.js','--production'],{env:{...process.env,PORT:'3011',BOOKS_FILE:file},stdio:['ignore','pipe','pipe']});
 p.stdout.on('data',data=>{if(data.toString().includes('ready')) resolve(p)});
 p.on('error',reject);p.stderr.on('data',data=>process.stderr.write(data));
});
const stop=p=>new Promise(resolve=>{p.once('exit',resolve);p.kill('SIGTERM')});
let processHandle;
try {
 processHandle=await start();
 const created=await (await fetch('http://localhost:3011/api/books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'Restart test',author:'Reader',notes:'Survives a full process restart.'})})).json();
 await stop(processHandle);
 processHandle=await start();
 const response=await fetch("'`http://localhost:3011/api/books/${created.id}`);
 const saved=await response.json();
 if(saved.notes!==created.notes)throw new Error('"'Restart lost notes');
 const html=await (await fetch("'`http://localhost:3011/books/${created.id}`)).text();
 if(!html.includes('"'<div id=\"root\"></div>'))throw new Error('Direct book URL did not return the app');
 const stored=JSON.parse(await readFile(file,'utf8'));
 if(stored.length"'!==7)throw new Error('"'Unexpected persisted count');
 console.log('Production startup, full process restart, JSON persistence, and direct-link fallback all passed.');
} finally {
 if(processHandle && processHandle.exitCode===null)await stop(processHandle);
 await rm(dir,{recursive:true,force:true});
}
