import {chromium,expect} from '@playwright/test';
const browser=await chromium.launch({headless:true});
const context=await browser.newContext({viewport:{width:1440,height:1000},permissions:['clipboard-read','clipboard-write']});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));
let bookId;
try {
 await page.goto('http://localhost:3000');
 await expect(page.locator('.book-card')).toHaveCount(6);
 await page.getByRole('button',{name:'Add a book',exact:true}).click();
 await expect(page.getByRole('dialog')).toBeVisible();
 await expect(page.getByLabel(/Book title/)).toBeFocused();
 await page.screenshot({path:'/tmp/marginalia-form.png',animations:'disabled'});
 await page.getByLabel(/Book title/).fill('A Browser-Test Book');
 await page.getByLabel(/"'^Author/).fill('"'A Test Reader');
 await page.getByLabel(/Your notes/).fill('My first thought.');
 await page.getByRole('button',{name:'Add to my library'}).click();
 await expect(page.getByRole('dialog')).toHaveCount(0);
 await page.getByRole('link',{name:'A Browser-Test Book',exact:true}).click();
 await expect(page.getByRole('heading',{name:'A Browser-Test Book',exact:true})).toBeVisible();
 bookId=page.url().split('/').at(-1);
 await expect(page.getByLabel('MY NOTES')).toHaveValue('My first thought.');
 await page.getByLabel('MY NOTES').fill('My saved thought.\\nAnd a favorite passage.');
 await page.getByRole('button',{name:'Save notes',exact:true}).click();
 await expect(page.getByText('All thoughts saved')).toBeVisible();
 await page.getByRole('button',{name:'Mark as finished',exact:true}).click();
 await expect(page.getByRole('button',{name:'Move to currently reading'})).toBeVisible();
 await page.getByRole('button',{name:'Share book',exact:true}).click();
 await expect(page.getByText('Book link copied. Ready to share.')).toBeVisible();
 expect(await page.evaluate(()=>navigator.clipboard.readText())).toBe(page.url());
 const direct=await context.newPage();
 await direct.goto(page.url());
 await expect(direct.getByLabel('MY NOTES')).toHaveValue('My saved thought.\\nAnd a favorite passage.');
 await expect(direct.getByRole('heading',{name:'A Browser-Test Book'})).toBeVisible();
 await direct.close();
 await page.getByRole('link',{name:'Back to my library'}).click();
 await page.getByRole('textbox',{name:'Search books'}).fill('A Browser-Test');
 await expect(page.locator('.book-card')).toHaveCount(1);
 await expect(page.locator('.status.finished')).toHaveCount(1);
 await page.getByRole('button',{name:'Clear search',exact:true}).click();
 await page.getByRole('combobox',{name:'Sort books'}).selectOption('title');
 const readingTitles=await page.locator('.book-section').first().locator('.book-title').allTextContents();
 expect(readingTitles).toEqual([...readingTitles].sort((a,b)=>a.localeCompare(b)));
 await page.goto('http://localhost:3000/books/the-creative-act');
 await expect(page.getByRole('heading',{name:'The Creative Act',exact:true})).toBeVisible();
 await page.screenshot({path:'/tmp/marginalia-detail.png',fullPage:true,animations:'disabled'});
 await page.goto('http://localhost:3000');
 await page.setViewportSize({width:390,height:844});
 await page.waitForTimeout(300);
 await page.screenshot({path:'/tmp/marginalia-mobile.png',fullPage:true,animations:'disabled'});
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.getByRole('button',{name:'Open navigation'}).click();
 await page.locator('nav').getByRole('link',{name:/Finished/}).click();
 await expect(page.getByRole('heading',{name:'Finished books.'})).toBeVisible();
 await expect(page.locator('.book-card')).toHaveCount(4);
 await page.goto("'`http://localhost:3000/books/${bookId}`);
 await page.getByRole('"'button',{name:'Remove book',exact:true}).click();
 await page.getByRole('dialog').getByRole('button',{name:'Remove book',exact:true}).click();
 await expect(page.getByRole('heading',{name:'My library.'})).toBeVisible();
 bookId=null;
 expect(errors).toEqual([]);
 console.log('Browser checks passed: form + focus, add, detail, notes, finish, clipboard, direct shared URL, search, sort, mobile navigation, delete, and no runtime errors.');
} finally {
 if(bookId)await fetch("'`http://localhost:3000/api/books/${bookId}`,{method:'"'DELETE'});
 await browser.close();
}
